package claudecode

import (
	"bytes"
	"sync"
	"testing"
)

func TestSetupTokenScreenSplit(t *testing.T) {
	var out bytes.Buffer
	var captured limitedBuffer
	var mu sync.Mutex
	screen := &tokenScreen{mu: &mu, out: &out, captured: &captured}
	const prompt = "Open the browser.\n"
	screen.Write([]byte(prompt + "Your OAuth"))
	screen.Write([]byte(" token:\n  fake-"))
	screen.Write([]byte("token_123\n"))
	screen.flush()
	if got := out.String(); got != prompt {
		t.Fatalf("forwarded output = %q, want only %q", got, prompt)
	}
}

func TestSetupTokenScreenWholeMarker(t *testing.T) {
	var out bytes.Buffer
	var captured limitedBuffer
	var mu sync.Mutex
	screen := &tokenScreen{mu: &mu, out: &out, captured: &captured}
	const prompt = "Open the browser.\n"
	screen.Write([]byte(prompt + "Your OAuth token:\n  fake-token_123\n"))
	if got := out.String(); got != prompt {
		t.Fatalf("output after marker write = %q, want only %q", got, prompt)
	}
	screen.Write([]byte("Store this token securely.\n"))
	screen.flush()
	if got := out.String(); got != prompt {
		t.Fatalf("output after later write = %q, want only %q", got, prompt)
	}
}

func TestParseSetupToken(t *testing.T) {
	for _, tc := range []struct{ name, screen, want string }{
		{"trimmed token", "Open the browser.\nYour OAuth token:\n  fake-token_123 \t\n", "fake-token_123"},
		{"no marker", "arbitrary-screen-text\n", ""},
		{"no token", "Your OAuth token:\n \t\n", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := parseSetupToken(tc.screen); got != tc.want {
				t.Fatalf("parsed token = %q, want %q", got, tc.want)
			}
		})
	}
}

